from typing import *

class Solution:
    def totalHammingDistance(self, nums: List[int]) -> int:
        if not nums:
            return 0

        total = 0
        # For each bit position, count how many numbers have 0 and how many have 1
        # The contribution to the total Hamming distance from this bit position is count_0 * count_1
        for i in range(32):
            count_ones = 0
            for num in nums:
                if (num >> i) & 1:
                    count_ones += 1
            count_zeros = len(nums) - count_ones
            total += count_ones * count_zeros

        return total
