from typing import *

class Solution:
    def goodDaysToRobBank(self, security: List[int], time: int) -> List[int]:
        n = len(security)
        if n == 0:
            return []

        # If time is 0, every day is a good day
        if time == 0:
            return list(range(n))

        # Precompute the number of consecutive non-increasing days ending at each index (from the left)
        # left[i] = number of consecutive days before i (including i) where security is non-increasing
        left = [0] * n
        for i in range(1, n):
            if security[i] <= security[i - 1]:
                left[i] = left[i - 1] + 1
            else:
                left[i] = 0

        # Precompute the number of consecutive non-decreasing days starting at each index (to the right)
        # right[i] = number of consecutive days after i (including i) where security is non-decreasing
        right = [0] * n
        for i in range(n - 2, -1, -1):
            if security[i] <= security[i + 1]:
                right[i] = right[i + 1] + 1
            else:
                right[i] = 0

        # A day i is good if:
        # - There are at least 'time' days before and after, so i >= time and i < n - time
        # - left[i] >= time (meaning there are at least 'time' non-increasing days ending at i)
        # - right[i] >= time (meaning there are at least 'time' non-decreasing days starting at i)
        result = []
        for i in range(n):
            if i >= time and i < n - time:
                if left[i] >= time and right[i] >= time:
                    result.append(i)

        return result
